'use client';

import { useState } from 'react';

import { Button } from '@shared/components/ui/button';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from '@shared/components/ui/dialog';
import { Input } from '@shared/components/ui/form/input';
import { Label } from '@shared/components/ui/label';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@shared/components/ui/select';
import { Textarea } from '@shared/components/ui/textarea';
import { Sparkles } from 'lucide-react';
import { toast } from 'sonner';

interface AiAutogenerateDialogProps {
  onGenerate: (generatedData: {
    templateNumber?: number;
    password?: string;
    additionalDetails?: string;
  }) => Promise<void>;
  disabled?: boolean;
}

export const AiAutogenerateDialog = ({ onGenerate, disabled }: AiAutogenerateDialogProps) => {
  const [open, setOpen] = useState(false);
  const [isGenerating, setIsGenerating] = useState(false);
  const [templateNumber, setTemplateNumber] = useState<string>('');
  const [password, setPassword] = useState('');
  const [additionalDetails, setAdditionalDetails] = useState('');

  const handleGenerate = async () => {
    setIsGenerating(true);
    try {
      await onGenerate({
        templateNumber: templateNumber ? parseInt(templateNumber) : undefined,
        password: password.trim() || undefined,
        additionalDetails: additionalDetails.trim() || undefined,
      });
      toast.success('Microsite generated successfully!');
      setOpen(false);
      // Reset form
      setTemplateNumber('');
      setPassword('');
      setAdditionalDetails('');
    } catch (error) {
      console.error('Error generating microsite:', error);
      toast.error('Failed to generate microsite. Please try again.');
    } finally {
      setIsGenerating(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger asChild>
        <Button type="button" variant="secondary" disabled={disabled} className="gap-2">
          <Sparkles className="h-4 w-4" />
          AI Autogenerate Microsite
        </Button>
      </DialogTrigger>
      <DialogContent className="sm:max-w-[550px]">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Sparkles className="h-5 w-5 text-purple-500" />
            AI Autogenerate Microsite
          </DialogTitle>
          <DialogDescription className="pt-3 space-y-2">
            <p>
              Our AI will use your existing wedding information (couple names, date, location) to
              create a beautiful microsite for you.
            </p>
            <p className="text-sm">
              Provide a few optional details below to personalize the generation, or leave them
              blank to use intelligent defaults.
            </p>
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-4 py-4">
          <div className="space-y-2">
            <Label htmlFor="template">Template (Optional)</Label>
            <Select
              value={templateNumber}
              onValueChange={setTemplateNumber}
              disabled={isGenerating}
            >
              <SelectTrigger id="template">
                <SelectValue placeholder="Select a template" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="1">Template 1</SelectItem>
                <SelectItem value="2">Template 2</SelectItem>
                <SelectItem value="3">Template 3</SelectItem>
              </SelectContent>
            </Select>
          </div>

          <div className="space-y-2">
            <Label htmlFor="password">Access Password (Optional)</Label>
            <Input
              id="password"
              type="text"
              placeholder="Password for guests to access the microsite"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              disabled={isGenerating}
            />
          </div>

          <div className="space-y-2">
            <Label htmlFor="additionalDetails">Additional Details (Optional)</Label>
            <Textarea
              id="additionalDetails"
              placeholder="Any special requests or details you'd like to include..."
              value={additionalDetails}
              onChange={(e) => setAdditionalDetails(e.target.value)}
              disabled={isGenerating}
              rows={4}
            />
          </div>
        </div>

        <DialogFooter>
          <Button variant="outline" onClick={() => setOpen(false)} disabled={isGenerating}>
            Cancel
          </Button>
          <Button onClick={handleGenerate} disabled={isGenerating} className="gap-2">
            {isGenerating ? (
              <>
                <Sparkles className="h-4 w-4 animate-pulse" />
                Generating...
              </>
            ) : (
              <>
                <Sparkles className="h-4 w-4" />
                Generate Microsite
              </>
            )}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
};
